        trace = [row['pointer_heads']['x1_head'][:16] for row in case_result['native_calls']['selected_drawable_redraw_lifecycle_method_entries'] if row['phase'] == 'draw_object_stroke' and any('::drawPoint(' in name for name in row['signatures'])]
        expected = json.loads((root / 'tools/marker3-size9-note-derived/native-receipt.json').read_text())['draw_point_input_xy_f32_le_hex']
        assert trace == expected
        assert ''.join(trace) == case_result['phase_final_vectors']['draw_object_stroke']['vector_bytes']
        print(case, tool, flush=True)
